CREATE TABLE students (
	-- GENERATED BY DEFAULT AS IDENTITY = automatically creates incremental number for each student
	student_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	-- varchar2 = oracle version for storing characters
	first_name VARCHAR2(50) NOT NULL,
	last_name VARCHAR2(50) NOT NULL,
	major VARCHAR2(50),
	-- 3 numbers total, 2 in precision§
	gpa NUMBER(3,2)
)

EXIT

